(function() {
    'use strict';

    class QueueLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Queue Lab: Service System Design';
            this.version = '1.1.0';

            this.CUSTOMER_TYPES = {
                A: { meanService: 0.12, cvLow: 0.35, cvMed: 1.0, cvHigh: 2.0 },
                B: { meanService: 0.22, cvLow: 0.35, cvMed: 1.0, cvHigh: 2.0 },
                C: { meanService: 0.48, cvLow: 0.35, cvMed: 1.0, cvHigh: 2.0 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    experimentsRun: 0,
                    bestP90: null,
                    lastUtilization: null,
                    lastP90: null,
                    p90History: [],
                    utilizationHistory: [],
                    meanWaitHistory: [],
                    p50History: [],
                    p95History: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    numServers: 2,
                    queueDiscipline: 'pooled',
                    arrivalRate: 4,
                    arrivalVar: 'medium',
                    serviceVar: 'medium',
                    pctTypeA: 40,
                    pctTypeB: 40
                };
            }
            this._updateTypeCDisplay();
        }

        _updateTypeCDisplay() {
            var aInput = document.getElementById('pctTypeAInput');
            var bInput = document.getElementById('pctTypeBInput');
            var cDisp = document.getElementById('pctTypeCDisplay');
            if (aInput && bInput && cDisp) {
                var a = parseInt(aInput.value) || 0;
                var b = parseInt(bInput.value) || 0;
                var c = Math.max(0, 100 - a - b);
                cDisp.textContent = c;
            }
        }

        validateDecisions(decisions) {
            var numServersEl = document.getElementById('numServersInput');
            if (numServersEl) decisions.numServers = parseInt(numServersEl.value);

            var qdEl = document.getElementById('queueDisciplineInput');
            if (qdEl) decisions.queueDiscipline = qdEl.value;

            var arEl = document.getElementById('arrivalRateInput');
            if (arEl) decisions.arrivalRate = parseFloat(arEl.value);

            var avEl = document.getElementById('arrivalVarInput');
            if (avEl) decisions.arrivalVar = avEl.value;

            var svEl = document.getElementById('serviceVarInput');
            if (svEl) decisions.serviceVar = svEl.value;

            var paEl = document.getElementById('pctTypeAInput');
            if (paEl) decisions.pctTypeA = parseInt(paEl.value);

            var pbEl = document.getElementById('pctTypeBInput');
            if (pbEl) decisions.pctTypeB = parseInt(pbEl.value);

            if (!decisions.arrivalRate || decisions.arrivalRate < 1 || decisions.arrivalRate > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('arrival_rate_warning'), 'warning'
                );
                return false;
            }

            var totalAB = (decisions.pctTypeA || 0) + (decisions.pctTypeB || 0);
            if (totalAB > 100 || totalAB < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('mix_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        _generateVariate(mean, cvLevel) {
            var cv;
            if (cvLevel === 'low') cv = 0.577;
            else if (cvLevel === 'high') cv = 2.0;
            else cv = 1.0;

            if (cv <= 0.6) {
                var k = 3;
                var rate = k / mean;
                var sum = 0;
                for (var i = 0; i < k; i++) {
                    sum += -Math.log(Math.random()) / rate;
                }
                return sum;
            } else if (cv <= 1.1) {
                return -Math.log(Math.random()) * mean;
            } else {
                var p1 = 0.2;
                var mu1 = mean / 4;
                var mu2 = mean * 4 / 3;
                if (Math.random() < p1) {
                    return -Math.log(Math.random()) * (1 / (1 / mu1));
                } else {
                    return -Math.log(Math.random()) * (1 / (1 / mu2));
                }
            }
        }

        _assignType(pctA, pctB) {
            var r = Math.random() * 100;
            if (r < pctA) return 'A';
            if (r < pctA + pctB) return 'B';
            return 'C';
        }

        _runSimulation(d) {
            var NUM_CUSTOMERS = 300;
            var WARMUP = 50;
            var lambda = d.arrivalRate;
            var numServers = d.numServers;
            var pctA = d.pctTypeA;
            var pctB = d.pctTypeB;
            var discipline = d.queueDiscipline;
            var arrivalVar = d.arrivalVar;
            var serviceVar = d.serviceVar;

            var customers = [];
            var arrivalTime = 0;
            for (var i = 0; i < NUM_CUSTOMERS; i++) {
                var interArrival = this._generateVariate(1 / lambda, arrivalVar);
                arrivalTime += interArrival;
                var type = this._assignType(pctA, pctB);
                var svcMean = this.CUSTOMER_TYPES[type].meanService;
                var svcTime = this._generateVariate(svcMean, serviceVar);
                customers.push({ arrival: arrivalTime, type: type, serviceTime: svcTime });
            }

            var waitTimes = [];
            var serverBusy = [];
            for (var s = 0; s < numServers; s++) {
                serverBusy.push(0);
            }

            var totalBusy = 0;
            var totalTime = 0;
            var queueLengthArea = 0;
            var lastEventTime = 0;
            var currentQueueLen = 0;

            if (discipline === 'pooled') {
                var queue = [];
                for (var ci = 0; ci < customers.length; ci++) {
                    var cust = customers[ci];
                    queueLengthArea += currentQueueLen * (cust.arrival - lastEventTime);
                    lastEventTime = cust.arrival;

                    var assigned = -1;
                    var earliest = Infinity;
                    for (var si = 0; si < numServers; si++) {
                        if (serverBusy[si] <= cust.arrival) {
                            if (serverBusy[si] < earliest) {
                                earliest = serverBusy[si];
                                assigned = si;
                            }
                        }
                    }

                    if (assigned >= 0) {
                        var startTime = cust.arrival;
                        var waitT = 0;
                        serverBusy[assigned] = startTime + cust.serviceTime;
                        totalBusy += cust.serviceTime;
                        if (ci >= WARMUP) waitTimes.push(waitT);
                    } else {
                        var minFinish = Infinity;
                        var minServer = 0;
                        for (var sj = 0; sj < numServers; sj++) {
                            if (serverBusy[sj] < minFinish) {
                                minFinish = serverBusy[sj];
                                minServer = sj;
                            }
                        }
                        var startT = minFinish;
                        var wt = startT - cust.arrival;
                        currentQueueLen++;
                        serverBusy[minServer] = startT + cust.serviceTime;
                        totalBusy += cust.serviceTime;
                        currentQueueLen = Math.max(0, currentQueueLen - 1);
                        if (ci >= WARMUP) waitTimes.push(wt);
                    }
                }
            } else if (discipline === 'separate') {
                var queues = [];
                for (var sq = 0; sq < numServers; sq++) queues.push([]);

                for (var ci2 = 0; ci2 < customers.length; ci2++) {
                    var cust2 = customers[ci2];
                    var shortestQ = 0;
                    var shortestLen = Infinity;
                    for (var qi = 0; qi < numServers; qi++) {
                        var ql = 0;
                        for (var qj = 0; qj < queues[qi].length; qj++) {
                            if (queues[qi][qj] > cust2.arrival) ql++;
                        }
                        var effLen = ql;
                        if (serverBusy[qi] > cust2.arrival) effLen++;
                        if (effLen < shortestLen) {
                            shortestLen = effLen;
                            shortestQ = qi;
                        }
                    }

                    var startT2;
                    if (serverBusy[shortestQ] <= cust2.arrival) {
                        startT2 = cust2.arrival;
                    } else {
                        startT2 = serverBusy[shortestQ];
                    }
                    var wt2 = startT2 - cust2.arrival;
                    serverBusy[shortestQ] = startT2 + cust2.serviceTime;
                    totalBusy += cust2.serviceTime;
                    queues[shortestQ].push(startT2 + cust2.serviceTime);
                    if (ci2 >= WARMUP) waitTimes.push(wt2);
                }
            } else {
                var typeQueues = { A: [], B: [], C: [] };
                var typeServers = {};

                if (numServers === 1) {
                    typeServers = { A: [0], B: [0], C: [0] };
                } else if (numServers === 2) {
                    typeServers = { A: [0], B: [0, 1], C: [1] };
                } else {
                    typeServers = { A: [0], B: [1], C: [2] };
                }

                for (var ci3 = 0; ci3 < customers.length; ci3++) {
                    var cust3 = customers[ci3];
                    var allowedServers = typeServers[cust3.type];
                    var bestServer = allowedServers[0];
                    var bestFinish = serverBusy[allowedServers[0]];
                    for (var as = 1; as < allowedServers.length; as++) {
                        if (serverBusy[allowedServers[as]] < bestFinish) {
                            bestFinish = serverBusy[allowedServers[as]];
                            bestServer = allowedServers[as];
                        }
                    }

                    var startT3;
                    if (serverBusy[bestServer] <= cust3.arrival) {
                        startT3 = cust3.arrival;
                    } else {
                        startT3 = serverBusy[bestServer];
                    }
                    var wt3 = startT3 - cust3.arrival;
                    serverBusy[bestServer] = startT3 + cust3.serviceTime;
                    totalBusy += cust3.serviceTime;
                    if (ci3 >= WARMUP) waitTimes.push(wt3);
                }
            }

            waitTimes.sort(function(a, b) { return a - b; });
            var n = waitTimes.length;
            if (n === 0) return null;

            var meanWait = waitTimes.reduce(function(s, v) { return s + v; }, 0) / n;
            var p50 = waitTimes[Math.floor(n * 0.5)];
            var p90 = waitTimes[Math.floor(n * 0.9)];
            var p95 = waitTimes[Math.min(Math.floor(n * 0.95), n - 1)];

            var lastDepart = 0;
            for (var fs = 0; fs < numServers; fs++) {
                if (serverBusy[fs] > lastDepart) lastDepart = serverBusy[fs];
            }
            var simDuration = lastDepart - customers[WARMUP].arrival;
            var utilization = totalBusy / (numServers * simDuration);
            utilization = Math.min(utilization, 0.99);

            var throughput = n / simDuration;

            var pctC = Math.max(0, 100 - pctA - pctB);
            var weightedMeanService = (pctA / 100) * 0.12 + (pctB / 100) * 0.22 + (pctC / 100) * 0.48;

            var cvArrMap = { low: 0.577, medium: 1.0, high: 2.0 };
            var cvSvcMap = { low: 0.577, medium: 1.0, high: 2.0 };
            var cva2 = Math.pow(cvArrMap[arrivalVar] || 1.0, 2);
            var cvs2 = Math.pow(cvSvcMap[serviceVar] || 1.0, 2);

            var rhoEff = utilization;
            var kingmanWait = ((cva2 + cvs2) / 2) * (rhoEff / (1 - rhoEff)) * weightedMeanService;
            if (numServers > 1) {
                kingmanWait = kingmanWait / numServers;
            }

            return {
                meanWait: Math.round(meanWait * 1000) / 1000,
                p50: Math.round(p50 * 1000) / 1000,
                p90: Math.round(p90 * 1000) / 1000,
                p95: Math.round(p95 * 1000) / 1000,
                utilization: Math.round(utilization * 1000) / 1000,
                throughput: Math.round(throughput * 100) / 100,
                avgQueueLen: Math.round(meanWait * lambda * 10) / 10,
                customersServed: n,
                kingmanWait: Math.round(kingmanWait * 1000) / 1000,
                cva2: cva2,
                cvs2: cvs2,
                rho: rhoEff,
                meanServiceTime: weightedMeanService
            };
        }

        calculateResults(state) {
            var d = state.decisions;
            var simResult = this._runSimulation(d);

            if (!simResult) {
                return {
                    period: state.currentPeriod,
                    error: true,
                    meanWait: 0, p50: 0, p90: 0, p95: 0,
                    utilization: 0, throughput: 0, avgQueueLen: 0, customersServed: 0,
                    kingmanWait: 0, numServers: d.numServers,
                    queueDiscipline: d.queueDiscipline
                };
            }

            state.domainState.experimentsRun++;
            state.domainState.lastUtilization = simResult.utilization;
            state.domainState.lastP90 = simResult.p90;
            if (state.domainState.bestP90 === null || simResult.p90 < state.domainState.bestP90) {
                state.domainState.bestP90 = simResult.p90;
            }

            state.domainState.p90History.push(simResult.p90);
            state.domainState.utilizationHistory.push(simResult.utilization);
            state.domainState.meanWaitHistory.push(simResult.meanWait);
            state.domainState.p50History.push(simResult.p50);
            state.domainState.p95History.push(simResult.p95);

            var results = {
                period: state.currentPeriod,
                numServers: d.numServers,
                queueDiscipline: d.queueDiscipline,
                arrivalRate: d.arrivalRate,
                arrivalVar: d.arrivalVar,
                serviceVar: d.serviceVar,
                pctTypeA: d.pctTypeA,
                pctTypeB: d.pctTypeB,
                meanWait: simResult.meanWait,
                p50: simResult.p50,
                p90: simResult.p90,
                p95: simResult.p95,
                utilization: simResult.utilization,
                throughput: simResult.throughput,
                avgQueueLen: simResult.avgQueueLen,
                customersServed: simResult.customersServed,
                kingmanWait: simResult.kingmanWait,
                cva2: simResult.cva2,
                cvs2: simResult.cvs2,
                rho: simResult.rho,
                meanServiceTime: simResult.meanServiceTime
            };

            var self = this;
            setTimeout(function() {
                self._showResults(results);
            }, 300);

            return results;
        }

        _showResults(r) {
            var panel = document.getElementById('resultsPanel');
            if (panel) panel.style.display = 'block';

            var el;
            el = document.getElementById('resUtilDisplay');
            if (el) el.textContent = (r.utilization * 100).toFixed(1) + '%';
            el = document.getElementById('resMeanWaitDisplay');
            if (el) el.textContent = r.meanWait.toFixed(2) + ' min';
            el = document.getElementById('resP50Display');
            if (el) el.textContent = r.p50.toFixed(2) + ' min';
            el = document.getElementById('resP90Display');
            if (el) el.textContent = r.p90.toFixed(2) + ' min';
            el = document.getElementById('resP95Display');
            if (el) el.textContent = r.p95.toFixed(2) + ' min';
            el = document.getElementById('resThroughputDisplay');
            if (el) el.textContent = r.throughput.toFixed(1) + ' /min';
            el = document.getElementById('resAvgQueueDisplay');
            if (el) el.textContent = r.avgQueueLen.toFixed(1);
            el = document.getElementById('resServedDisplay');
            if (el) el.textContent = r.customersServed;

            var kf = document.getElementById('kingmanFormula');
            if (kf) {
                var rhoTerm = r.rho < 0.99 ? (r.rho / (1 - r.rho)).toFixed(2) : '>99';
                kf.innerHTML = 'CT_q = [(' + r.cva2.toFixed(2) + ' + ' + r.cvs2.toFixed(2) + ') / 2]'
                    + ' x [' + rhoTerm + ']'
                    + ' x [' + r.meanServiceTime.toFixed(3) + ']'
                    + ' = <strong>' + r.kingmanWait.toFixed(3) + ' min</strong>'
                    + '<br>Simulated Mean Wait = <strong>' + r.meanWait.toFixed(3) + ' min</strong>';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('experimentsDisplay', 'domainState.experimentsRun');
            uiManager.bind('utilizationDisplay', 'domainState.lastUtilization',
                function(v) { return v !== null ? (v * 100).toFixed(1) + '%' : '--'; });
            uiManager.bind('p90Display', 'domainState.lastP90',
                function(v) { return v !== null ? v.toFixed(2) : '--'; });
            uiManager.bind('bestP90Display', 'domainState.bestP90',
                function(v) { return v !== null ? v.toFixed(2) : '--'; });

            var self = this;
            var aInput = document.getElementById('pctTypeAInput');
            var bInput = document.getElementById('pctTypeBInput');
            if (aInput) aInput.addEventListener('input', function() { self._updateTypeCDisplay(); });
            if (bInput) bInput.addEventListener('input', function() { self._updateTypeCDisplay(); });
        }

        getChartConfig() {
            return {
                p90Chart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'P90 Wait (min)',
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: 'P50 Wait (min)',
                                data: [],
                                borderColor: '#3498db',
                                backgroundColor: 'rgba(52,152,219,0.05)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                borderDash: [5, 5]
                            },
                            {
                                label: 'Mean Wait (min)',
                                data: [],
                                borderColor: '#2ecc71',
                                backgroundColor: 'rgba(46,204,113,0.05)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                borderDash: [2, 3]
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Waiting Time Across Experiments' } },
                        scales: { y: { beginAtZero: true, title: { display: true, text: 'Minutes' } } }
                    }
                },
                utilizationChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Server Utilization',
                            data: [],
                            backgroundColor: 'rgba(52,152,219,0.6)',
                            borderColor: '#2980b9',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Utilization Per Experiment' } },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 1.0,
                                title: { display: true, text: 'Utilization' },
                                ticks: { callback: function(v) { return (v * 100) + '%'; } }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.p90History.map(function(_, i) { return 'E' + (i + 1); });
            return {
                p90Chart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.p90History },
                        { data: state.domainState.p50History },
                        { data: state.domainState.meanWaitHistory }
                    ]
                },
                utilizationChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.utilizationHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var p90s = history.map(function(r) { return r.results ? r.results.p90 || 0 : 0; });
            var utils = history.map(function(r) { return r.results ? r.results.utilization || 0 : 0; });
            var bestP90 = Math.min.apply(null, p90s);
            var avgUtil = utils.reduce(function(s, v) { return s + v; }, 0) / utils.length;
            var pooledRuns = history.filter(function(r) { return r.results && r.results.queueDiscipline === 'pooled'; });
            var separateRuns = history.filter(function(r) { return r.results && r.results.queueDiscipline === 'separate'; });

            var insights = [];
            if (bestP90 < 0.5) {
                insights.push('Excellent! You achieved a very low P90 waiting time below 30 seconds.');
            } else if (bestP90 < 2) {
                insights.push('Good results. Your best P90 wait was under 2 minutes.');
            } else {
                insights.push('Consider adding servers or switching to a pooled queue to reduce P90 wait times.');
            }

            if (pooledRuns.length > 0 && separateRuns.length > 0) {
                var avgPooledP90 = pooledRuns.reduce(function(s, r) { return s + r.results.p90; }, 0) / pooledRuns.length;
                var avgSepP90 = separateRuns.reduce(function(s, r) { return s + r.results.p90; }, 0) / separateRuns.length;
                if (avgPooledP90 < avgSepP90) {
                    var pctBetter = ((avgSepP90 - avgPooledP90) / avgSepP90 * 100).toFixed(0);
                    insights.push('Pooled queues reduced P90 wait by approximately ' + pctBetter + '% versus separate queues.');
                }
            }

            var performance = 'Beginner';
            if (history.length >= 6 && bestP90 < 1) performance = 'Excellent';
            else if (history.length >= 4 && bestP90 < 2) performance = 'Good';
            else if (history.length >= 3) performance = 'Developing';

            return {
                bestP90: bestP90,
                avgUtilization: avgUtil,
                experimentsRun: history.length,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results || results.error) return null;

            if (results.utilization > 0.92) {
                return window.mySimulation.t('hint_high_util');
            }
            if (results.p90 > 3 && results.queueDiscipline !== 'pooled') {
                return window.mySimulation.t('hint_try_pooled');
            }
            if (results.p90 > 2 && results.numServers < 3) {
                return window.mySimulation.t('hint_add_server');
            }
            if (results.p95 > results.p50 * 5) {
                return window.mySimulation.t('hint_tail');
            }
            if (results.utilization < 0.5 && results.numServers > 1) {
                return window.mySimulation.t('hint_over_capacity');
            }
            if (results.p90 < 0.5) {
                return window.mySimulation.t('hint_great');
            }
            return null;
        }

